def heritage_hero(eyebrow,title,lead,image,alt,depth=''):
 asset=image if '/' in image else 'visual-story/'+image
 return f'''<section class="heritage-hero"><div class="heritage-hero-copy"><p class="eyebrow light">{eyebrow}</p><h1>{title}</h1><p class="heritage-hero-lead">{lead}</p></div><figure class="heritage-hero-media"><img src="{depth}assets/{asset}" alt="{alt}" width="1536" height="1024"></figure></section>'''

def chapter(number,label,body,paper=False):
 return f'''<section class="heritage-chapter{' paper' if paper else ''}"><div class="heritage-grid"><div class="heritage-index"><strong>{number}</strong>{label}</div><div class="heritage-prose">{body}</div></div></section>'''

def render_heritage(path):
 depth='../' if path=='story-behind-the-brand/index.html' else ''
 if path in ['about-us.html','story-behind-the-brand/index.html']:
  hero=heritage_hero('The SANDY D. CARTER story','An idea born<br>in Amsterdam.<em>Shaped by three creative minds.</em>','Between 2009 and 2013, Rajan Mehta’s years in the Netherlands became the setting for a watch-brand idea shaped by international experience, European design and three complementary perspectives.','01-amsterdam-inspiration-branded-web.jpg','Amsterdam canal houses representing the creative birthplace of SANDY D. CARTER',depth)
  body=chapter('01','The Netherlands · 2009–2013','''<p class="lede">The story begins with a founder, a formative European chapter and an ambition to create an independent watch brand.</p><h2>The Amsterdam beginning.</h2><p>From 2009 to 2013, Rajan Mehta lived and worked in the Netherlands. His professional experience in the watch category included Danish Design and Jacob Jensen, strengthening his appreciation for minimalist thinking, proportion, functionality and refined product presentation.</p><p>Danish Design carries a Scandinavian-inspired identity; Jacob Jensen has Danish design heritage. These references describe Rajan’s professional exposure and do not imply endorsement of SANDY D. CARTER.</p><p>A larger ambition began to take shape: a watch brand with a distinctive European identity, built around simplicity with character rather than unnecessary complexity.</p><div class="evidence-note"><strong>Evidence note:</strong> Rajan’s professional background is documented on his official website. The 2009–2013 Netherlands period and founding history are supplied through his firsthand account.</div>''')
  body+=chapter('02','Three creative perspectives','''<h2>Vision. Expression.<br>Watch-design discipline.</h2><p>In Amsterdam, Rajan connected with Sandy, a Dutch illustrator and creative professional, and Carter, a senior male designer described by Rajan as experienced in European watch design.</p><div class="perspective-grid"><article><span>Founder · vision</span><h3>Rajan Mehta</h3><p>International watch-industry experience, entrepreneurial direction and the bridge from creative idea to commercial brand.</p></article><article><span>Creative perspective</span><h3>Sandy</h3><p>Individuality, expressive visual thinking, contemporary aesthetics and design that communicates.</p></article><article><span>Watch-design perspective</span><h3>Carter</h3><p>Proportion, product aesthetics, materials, finishing and the balance between appearance and function.</p></article></div><p>Rajan is the founder. Sandy and Carter are described as original creative collaborators, not legal co-founders.</p>''',True)
  body+=chapter('03','The collaborators','''<h2>Different backgrounds.<br>A shared design DNA.</h2><h3>Sandy · the creative perspective</h3><p>Sandy’s publicly documented professional background identifies her as a Dutch illustrator based in Amsterdam. She completed a BA in Illustration at Willem de Kooning Academy in 2013 and established her independent studio in 2015. Her practice spans illustration, campaigns, packaging, retail environments, murals and brand identity, with a visual language known for curved lines, confident composition, colour and storytelling.</p><p>Her published portfolio includes work for UNIQLO, Nike, Spotify, IKEA, Google Home and Benefit Cosmetics. Those names are portfolio context only; none is presented as endorsing SANDY D. CARTER.</p><h3>Carter · the watch design perspective</h3><p>Carter is described by the founder as a senior designer, based in the Netherlands during the formative period, whose contribution included watch proportions, product aesthetics, materials, finishing and timeless rather than trend-driven thinking.</p><p>Carter’s full name, education, employers, qualifications and portfolio remain pending documentary verification. No unsupported details are supplied.</p><p><a class="text-link" href="{depth}our-people.html">Meet the three perspectives</a></p>''')
  body+=chapter('04','Droog Amsterdam · the meaning of D','''<h2>Three elements.<br>One identity.</h2><p>Some ideas are born in studios. Others take shape through conversations, creative perspectives and a shared ambition. According to Rajan Mehta’s firsthand account, the original conversations involving Rajan, Sandy and Carter took place at Droog Amsterdam, Staalstraat 7B.</p><p>The place became part of the brand’s origin story, and the letter D was chosen as a tribute to where the idea took shape.</p><div class="name-key"><div><strong>SANDY</strong><span>The creative perspective.</span></div><div><strong>D</strong><span>A tribute to Droog Amsterdam.</span></div><div><strong>CARTER</strong><span>The watch-design perspective.</span></div></div><div class="evidence-note">Droog Amsterdam is not a co-founder, owner, investor, manufacturer, designer, endorser or official affiliate. The relationship stated here is historical and based on the founder’s account.</div>''')
  body+=chapter('05','India · 17 December 2014','''<h2>From creative vision<br>to formal identity.</h2><p>Following the original creative development in Amsterdam, a SANDY D. CARTER trademark application was filed in India on 17 December 2014 in Class 14, identifying Rajan Mehta as the applicant.</p><p>House Of Brands Fashion LLP was established in India in 2015. Founded by Rajan, the business provides experience across e-commerce, product sourcing and development, brand building, retail and marketplace distribution.</p><div class="trademark-card"><h4>A deliberately international foundation</h4><dl><div><dt>Creative conception</dt><dd>Amsterdam, Netherlands</dd></div><div><dt>Creative perspectives</dt><dd>Rajan · Sandy · Carter</dd></div><div><dt>Trademark application</dt><dd>India · 17 December 2014</dd></div><div><dt>Business support</dt><dd>House Of Brands Fashion LLP</dd></div></dl></div><p>Myntra is described as a marketplace partner of House Of Brands. It is not presented as owner, founder or exclusive distributor of SANDY D. CARTER.</p>''',True)
  body+=chapter('06','The next chapter','''<h2>Envisioned for the world.</h2><p>SANDY D. CARTER is preparing for its renewed India launch in December 2026. The Netherlands remains its creative birthplace and a future market ambition.</p><p>The wider plan looks towards the United Arab Emirates, the United Kingdom—particularly London—and the United States, including a future Los Angeles office presence. These are future intentions, not claims of current operations or confirmed retail locations.</p><div class="world-markets"><article><span>Creative birthplace</span><h3>Amsterdam</h3><p>The setting of the original idea and a future European market.</p></article><article><span>Planned launch</span><h3>India</h3><p>Next major chapter · December 2026.</p></article><article><span>Future market</span><h3>UAE</h3><p>Part of the international ambition.</p></article><article><span>Future market</span><h3>London</h3><p>An intended United Kingdom market.</p></article><article><span>Future presence</span><h3>Los Angeles</h3><p>A planned office ambition; not currently operational.</p></article></div>''')
  body+=f'''<section class="packaging-feature" aria-labelledby="identity-detail-title"><div><p class="eyebrow">An identity in every detail</p><h2 id="identity-detail-title">The philosophy,<br>made tangible.</h2><p>The midnight-navy presentation box carries the same understated Amsterdam-inspired identity as the brand itself: the original SC monogram, the SANDY D. CARTER wordmark and a disciplined white-on-navy composition.</p><p>The packaging is a contemporary expression of the brand—not presented as archival evidence of the founding meetings.</p></div><figure><img src="{depth}assets/brand/packaging-reference.jpeg" alt="Actual SANDY D. CARTER midnight-navy watch packaging with white logo lockup" width="1536" height="1024" loading="lazy"></figure></section>'''
  body+=f'''<section class="heritage-cta"><p class="eyebrow light">TIME. REFINED.</p><h2>Different cities. Different perspectives. One design philosophy.</h2><p>Meet the people behind the Amsterdam-born vision, or explore the first collection direction ahead of the planned India launch.</p><a class="button button-light" href="{depth}our-people.html">Meet our people</a> <a class="button button-light" href="{depth}shop.html">Explore the collection</a></section>'''
  return hero+body
 if path=='our-people.html':
  hero=heritage_hero('Our people','Three perspectives.<em>One original idea.</em>','The founder’s international watch experience, Sandy’s expressive visual language and Carter’s watch-design perspective came together in Amsterdam to shape the original thinking behind SANDY D. CARTER.','02-idea-takes-shape-branded-web.jpg','Abstract watch sketches representing three creative perspectives')
  body=chapter('01','Rajan · founder and visionary','''<div class="people-profile founder"><figure><img src="assets/founder/rajan-mehta-baselworld.jpg" alt="Rajan Mehta, founder of SANDY D. CARTER, at the Baselworld watch trade fair" width="1200" height="1500"></figure><div><p class="evidence-label">Public professional profile + founder account</p><h2>Rajan Mehta</h2><p class="lede">The vision to create an independent international watch brand.</p><p>Rajan Mehta is an entrepreneur and watch-industry professional whose work spans product development, sourcing, manufacturing, brand building, e-commerce and marketplace strategy. His official professional profile documents experience with international names including Danish Design and Jacob Jensen in the watch category.</p><p>From 2009 to 2013, Rajan lived and worked in the Netherlands. According to his firsthand account, that period sharpened his appreciation of European product aesthetics, proportion, functional elegance and considered presentation—and inspired the ambition that became SANDY D. CARTER.</p><p>Danish Design is referenced for its Scandinavian-inspired watch identity; Jacob Jensen for its Danish design heritage. Their names document Rajan’s professional experience and do not imply endorsement of SANDY D. CARTER.</p><a class="text-link" href="founder.html">Read the founder story</a></div></div>''')
  body+=chapter('02','Sandy · creative perspective','''<div class="people-profile abstract"><figure class="type-portrait" aria-label="Typographic portrait for Sandy; no personal photograph used"><span>S</span><strong>SANDY</strong><small>Expression · individuality · visual storytelling</small></figure><div><p class="evidence-label">Public professional profile + founder account</p><h2>Sandy — The Creative Perspective</h2><p class="lede">An expressive visual perspective rooted in illustration, identity and storytelling.</p><p>Sandy is a Dutch illustrator and creative professional based in Amsterdam. Her public biography describes a studio founded in 2015 and work spanning campaigns, brand illustration, packaging, retail environments, murals and editorial projects.</p><p>She completed a BA in Illustration at Willem de Kooning Academy in Rotterdam in 2013. Her published work is recognised for confident curved lines, vivid colour, strong composition and an ability to translate stories into a distinct visual language.</p><p>Her public portfolio includes work for names such as UNIQLO, Nike, Spotify, IKEA, Google Home and Benefit Cosmetics. Those portfolio references do not indicate that any of those organisations endorses or is connected with SANDY D. CARTER.</p><p>According to Rajan Mehta’s firsthand account, Sandy’s role in the founding conversations was to bring individuality, expression, contemporary visual culture and personality into the original brand thinking.</p><a class="text-link" href="https://www.sandyvanhelden.com/" target="_blank" rel="noopener noreferrer">View Sandy’s public portfolio</a></div></div>''',True)
  body+=chapter('03','Carter · watch-design perspective','''<div class="people-profile abstract"><figure class="type-portrait dark" aria-label="Typographic profile for Carter; no personal photograph used"><span>C</span><strong>CARTER</strong><small>Proportion · function · material thinking</small></figure><div><p class="evidence-label pending">Founder-supplied history · credentials pending verification</p><h2>Carter — The Watch Design Perspective</h2><p class="lede">A mature watch-design perspective balancing form, function and lasting proportion.</p><p>Carter is described by the founder as a senior male designer who was based in the Netherlands during the formative period, with experience in European watch design and the watch industry.</p><p>His contribution centred on watch proportions, case and dial aesthetics, material considerations, functional elegance and product balance. That technical and product-oriented perspective complemented Sandy’s expressive visual thinking and Rajan’s entrepreneurial vision.</p><p>Carter’s full legal name, education, employers, qualifications, portfolio and individual projects have not yet been independently documented for publication. No unsupported institution, brand affiliation, award or watch design is attributed to him.</p></div></div>''')
  body+=chapter('04','The shared perspective','''<h2>Three creative minds.<br>One design DNA.</h2><p>Rajan brought the ambition and bridge to commercial reality. Sandy brought expressive individuality and visual storytelling. Carter brought watch-design discipline, proportion and material thinking.</p><p>According to the founder’s account, their discussions at Droog Amsterdam explored how those three perspectives could become an independent watch brand—simple without anonymity, functional without coldness and expressive without unnecessary complexity.</p><div class="evidence-note"><strong>Roles stated with care:</strong> Rajan Mehta is the founder. Sandy and Carter are described as original creative collaborators, not legal co-founders. Droog Amsterdam is the historical meeting place, not a commercial partner or affiliate.</div>''',True)
  return hero+body+'''<section class="heritage-cta"><p class="eyebrow light">The founding story</p><h2>A moment, a place and three perspectives.</h2><a class="button button-light" href="about-us.html">Discover the complete story</a></section>'''
 if path=='founder.html':
  hero=heritage_hero('Founder · Rajan Mehta','A global journey.<em>One considered vision.</em>','Rajan Mehta’s experience across India, Europe, the Netherlands, the Middle East and China shaped an ambition: to create a watch brand with European design roots and international relevance.','founder/rajan-mehta-baselworld.jpg','Rajan Mehta, founder of SANDY D. CARTER')
  body=chapter('01','The founder','''<div class="founder-profile"><figure class="founder-portrait"><img src="assets/founder/rajan-mehta-baselworld.jpg" alt="Rajan Mehta at the Baselworld watch trade fair" width="1200" height="1500"><figcaption>Rajan Mehta · Founder of SANDY D. CARTER and House Of Brands Fashion LLP</figcaption></figure><div><p class="lede">An entrepreneur, product developer and brand builder with more than 25 years of experience in watches, fashion accessories and lifestyle products.</p><h2>From product to brand.</h2><p>Rajan Mehta’s career spans product development, sourcing, manufacturing, packaging, retail strategy and e-commerce. His international experience includes work across India, Europe, the Middle East and China, bringing together an understanding of how ideas move from first concept to commercial reality.</p><p>From 2009 to 2014, Rajan lived and worked in Amsterdam. The city’s creative culture and approach to purposeful design became the backdrop for the original SANDY D. CARTER idea.</p><h3>The Amsterdam vision</h3><p>Rajan wanted to create an international watch brand that felt considered rather than conventional. Through discussions with designers Sandy and Carter at Droog Amsterdam, that ambition developed into a philosophy centred on simplicity, proportion, balance and character.</p><blockquote class="founder-quote">“During my years in Amsterdam, I began imagining a watch brand that would reflect the design values I admired in Europe. SANDY D. CARTER grew from those conversations, creative perspectives and a belief that simplicity can create something truly distinctive.”<span class="quote-status">Proposed founder statement · requires Rajan Mehta’s approval before it is treated as a verbatim quotation</span></blockquote><h3>Building the business foundation</h3><p>Rajan founded House Of Brands Fashion LLP, established in India in 2015. Its experience in product development, international sourcing, e-commerce, brand building and marketplace distribution provides the commercial foundation for SANDY D. CARTER’s next chapter.</p><h3>A long-term international view</h3><p>His ambition is to reconnect the brand with the Netherlands, launch its renewed identity in India in December 2026, and build future relevance across the UAE, London and Los Angeles—one market at a time, without losing the clarity of the original Amsterdam idea.</p><p><a class="text-link" href="https://rajanmehta.in/" target="_blank" rel="noopener noreferrer">Visit Rajan Mehta’s official website</a></p></div></div>''')
  return hero+body+'''<section class="heritage-cta"><p class="eyebrow light">The complete story</p><h2>An idea shaped by place, people and purpose.</h2><a class="button button-light" href="about-us.html">Discover our story</a></section>'''
 if path=='design-philosophy.html':
  hero=heritage_hero('Our design philosophy','Considered,<br>not complicated.<em>European by instinct.</em>','Born from a creative vision in Amsterdam, our philosophy brings together Dutch design sensibilities and a contemporary understanding of time.','03-creative-philosophy-branded-web.jpg','Watch sketches and material studies representing the SANDY D. CARTER design philosophy')
  body=chapter('01','The principles','''<p class="lede">True refinement does not demand attention. It earns it through proportion, purpose and character.</p><h2>Design that leaves<br>room to breathe.</h2><p>We begin with clarity: what the watch needs to communicate, how it should sit on the wrist and which details deserve to remain. Simplicity is not emptiness. It is the result of choosing carefully.</p><div class="principles-editorial"><article><span>01</span><h3>Timelessness</h3><p>Coherent choices that can live beyond a temporary trend.</p></article><article><span>02</span><h3>Simplicity</h3><p>A disciplined edit that reveals character instead of removing it.</p></article><article><span>03</span><h3>Proportion</h3><p>Dial, bezel, case, lugs and crown considered as one composition.</p></article><article><span>04</span><h3>Thoughtful detail</h3><p>Typography, texture, colour and finishing used with intention.</p></article><article><span>05</span><h3>Functional elegance</h3><p>Legibility, comfort and daily usefulness as part of the aesthetic.</p></article><article><span>06</span><h3>Understatement</h3><p>Confidence expressed through restraint rather than excess.</p></article><article><span>07</span><h3>Individuality</h3><p>A quiet point of view that makes each design recognisable.</p></article></div>''')
  body+=chapter('02','Amsterdam influence','''<h2>Dutch design,<br>international outlook.</h2><p>Amsterdam’s architecture often brings old and new into the same frame. Dutch design culture pairs clear thinking with unexpected personality. Those ideas inform our approach without becoming a costume or a claim of manufacture.</p><p>Droog Amsterdam matters as the historical setting for the founding creative discussions. It did not manufacture, approve or officially endorse SANDY D. CARTER watches.</p><h3>Material and finishing</h3><p>Materials and finishes will be specified model by model once the launch collection is approved. Our design direction favours contrasts that reveal form: brushed against polished, open space against fine markers, restrained colour against the natural character of metal or leather.</p><h3>Designed beyond trends</h3><p>A timeless watch need not be anonymous. We look for the point at which an object feels calm but still personal—recognisable through its relationships, not through unnecessary decoration.</p>''',True)
  body+=chapter('03','Three perspectives','''<h2>One philosophy,<br>shaped from three directions.</h2><div class="perspective-grid"><article><span>Rajan · vision</span><h3>International positioning</h3><p>European watch-industry exposure, product thinking and the ambition to build an independent international brand.</p></article><article><span>Sandy · expression</span><h3>Individual character</h3><p>Visual storytelling, confident composition and the belief that simplicity can still communicate personality.</p></article><article><span>Carter · watch design</span><h3>Form and function</h3><p>Proportion, materials, finishing and timeless product thinking grounded in the watch category.</p></article></div><p>These contributions describe the original creative philosophy as supplied by the founder. They do not imply endorsements by the brands in Rajan’s or Sandy’s professional portfolios.</p>''')
  return hero+body+'''<section class="heritage-cta"><p class="eyebrow light">TIME. REFINED.</p><h2>Refinement through proportion, purpose and character.</h2><a class="button button-light" href="shop.html">Explore the collection direction</a></section>'''
 if path=='our-journey.html':
  hero=heritage_hero('Our journey','Amsterdam, India<em>and the road ahead.</em>','A timeline separating public professional facts, the founder’s firsthand history and milestones still awaiting documentary detail.','05-concept-to-creation-branded-web.jpg','Design sketches and watch forms representing the SANDY D. CARTER journey')
  body=chapter('01','The timeline','''<h2>A story built<br>across borders.</h2><div class="timeline-editorial"><article><time>2009</time><div><h3>The Netherlands journey begins</h3><p>According to his firsthand account, Rajan Mehta begins living and working in the Netherlands.</p></div></article><article><time>2009–2013</time><div><h3>The original ambition develops</h3><p>Professional experience in the watch category—including documented associations with Danish Design and Jacob Jensen—strengthens Rajan’s understanding of European design and international brand positioning.</p></div></article><article><time>2013</time><div><h3>Sandy completes her Illustration degree</h3><p>Public profiles document Sandy’s BA in Illustration from Willem de Kooning Academy, Rotterdam.</p></div></article><article><time>Formative period</time><div><h3>Three perspectives meet in Amsterdam</h3><p>Rajan’s firsthand account places the founding discussions with Sandy and Carter at Droog Amsterdam. No unsupported meeting date is assigned.</p></div></article><article><time>17 Dec 2014</time><div><h3>The Indian trademark application</h3><p>A SANDY D. CARTER application is filed in India in Class 14, identifying Rajan Mehta as applicant.</p></div></article><article><time>2015</time><div><h3>House Of Brands is established</h3><p>House Of Brands Fashion LLP is established in India, providing experience across development, sourcing, e-commerce and marketplace distribution.</p></div></article><article><time>2026</time><div><h3>A renewed identity</h3><p>SANDY D. CARTER prepares for its planned December India launch, with Myntra expected to play a role in the marketplace strategy.</p></div></article><article><time>Future</time><div><h3>From Amsterdam to the world</h3><p>Ambitions include the Netherlands, UAE, UK and a future Los Angeles office presence. These are not current operations.</p></div></article></div><div class="evidence-note"><strong>Pending verification:</strong> Carter’s full identity, qualifications, employers and portfolio; the precise dates of the Droog meetings; and final operational details for future markets.</div>''')
  return hero+body+'''<section class="heritage-cta"><p class="eyebrow light">The next chapter</p><h2>Different cities. Different cultures. One design philosophy.</h2><a class="button button-light" href="about-us.html">Read the complete story</a></section>'''
 if False and path=='our-journey.html':
  hero=heritage_hero('Our journey','Amsterdam, India<em>and the road ahead.</em>','A timeline of the documented milestones behind SANDY D. CARTER—from Rajan Mehta’s Amsterdam years to the planned December 2026 India launch.','05-concept-to-creation-branded-web.jpg','Design sketches and watch forms representing the SANDY D. CARTER journey')
  body=chapter('01','Documented milestones','''<h2>A story built<br>across borders.</h2><div class="timeline-editorial"><article><time>2009</time><div><h3>The Amsterdam journey begins</h3><p>Rajan Mehta begins living and working in Amsterdam, Netherlands.</p></div></article><article><time>2009–2014</time><div><h3>The original vision develops</h3><p>His experience of Dutch and wider European design culture shapes the ambition for an international watch brand.</p></div></article><article><time>During these years</time><div><h3>A creative collaboration takes shape</h3><p>Rajan connects with designers Sandy and Carter. Their founding design discussions take place at Droog Amsterdam. No unsupported exact meeting date is assigned.</p></div></article><article><time>Dec 2014</time><div><h3>The Indian trademark application</h3><p>The SANDY D. CARTER trademark application is filed in India on 17 December 2014, distinguishing the brand’s legal foundation from its Amsterdam creative origin.</p></div></article><article><time>2015</time><div><h3>House Of Brands is established</h3><p>House Of Brands Fashion LLP is incorporated in India, building expertise across development, sourcing, e-commerce and distribution.</p></div></article><article><time>Previous years</time><div><h3>Products enter the Indian marketplace</h3><p>Brand products appear in the Indian marketplace. Exact first-sale dates are not asserted without further documentation.</p></div></article><article><time>2026</time><div><h3>A renewed identity</h3><p>SANDY D. CARTER prepares for its planned December India launch, with Myntra forming an important part of the marketplace strategy.</p></div></article><article><time>Future</time><div><h3>From Amsterdam to the world</h3><p>Planned ambitions include the Netherlands, UAE, UK and a future Los Angeles office presence. These are not presented as current operations.</p></div></article></div>''')
  return hero+body+'''<section class="heritage-cta"><p class="eyebrow light">The next chapter</p><h2>Different cities. One design philosophy.</h2><a class="button button-light" href="about-us.html">Read the complete story</a></section>'''
 return None

def edit(text,path):
 soup=BeautifulSoup(text,'html.parser');data=EXTRA.get(path) or PAGES.get(path)
 depth='../' if path=='story-behind-the-brand/index.html' else ''
 heritage=render_heritage(path)
 if heritage:
  main=soup.select_one('#main')
  if main:
   main.clear();main.append(BeautifulSoup(heritage,'html.parser'))
  if soup.body:soup.body['data-page']='heritage'
  title,description=HERITAGE_META[path]
